from functools import reduce
import operator

class Solution:
    def xorAllNums(self, nums1: list[int], nums2: list[int]) -> int:
        res = 0
        if len(nums2) % 2 == 1:
            res ^= reduce(operator.xor, nums1)
        if len(nums1) % 2 == 1:
            res ^= reduce(operator.xor, nums2)
        return res

class Solution {
public:
    int xorAllNums(std::vector<int>& nums1, std::vector<int>& nums2) {
        int res = 0;
        if (nums2.size() % 2 == 1) {
            for (int x : nums1) res ^= x;
        }
        if (nums1.size() % 2 == 1) {
            for (int x : nums2) res ^= x;
        }
        return res;
    }
};

class Solution {
    public int xorAllNums(int[] nums1, int[] nums2) {
        int res = 0;
        if (nums2.length % 2 == 1) {
            for (int x : nums1) res ^= x;
        }
        if (nums1.length % 2 == 1) {
            for (int x : nums2) res ^= x;
        }
        return res;
    }
}

